/**
 * ConfirmDialog Styles
 */

.modal-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-4);
  z-index: var(--z-modal-backdrop);
}

.modal-content {
  background: var(--white);
  border-radius: var(--radius-2xl);
  box-shadow: var(--shadow-2xl);
  max-width: 500px;
  width: 100%;
  max-height: 90vh;
  overflow-y: auto;
  z-index: var(--z-modal);
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-6);
  border-bottom: 1px solid var(--gray-200);
}

.modal-title {
  font-size: var(--text-xl);
  font-weight: var(--font-bold);
  color: var(--gray-900);
  margin: 0;
}

.modal-close {
  color: var(--gray-500);

  &:hover {
    color: var(--gray-700);
  }
}

.modal-body {
  padding: var(--space-6);
}

.modal-message {
  font-size: var(--text-base);
  color: var(--gray-700);
  line-height: var(--leading-relaxed);
  margin: 0;
}

.modal-footer {
  display: flex;
  gap: var(--space-3);
  justify-content: flex-end;
  padding: var(--space-6);
  border-top: 1px solid var(--gray-200);
}

/* Mobile responsive */
@media (max-width: 767px) {
  .modal-content {
    max-width: 100%;
    margin: var(--space-4);
  }

  .modal-header,
  .modal-body,
  .modal-footer {
    padding: var(--space-4);
  }

  .modal-footer {
    flex-direction: column-reverse;

    .btn {
      width: 100%;
    }
  }
}

/* Focus trap */
.modal-content:focus {
  outline: none;
}

import { Component, Input, Output, EventEmitter, HostListener } from '@angular/core';
import { CommonModule } from '@angular/common';

/**
 * ConfirmDialog Component
 * Modal de confirmación reutilizable
 * 
 * @example
 * <app-confirm-dialog
 *   *ngIf="showDialog"
 *   title="Eliminar espacio"
 *   message="¿Estás seguro de que quieres eliminar este espacio?"
 *   confirmText="Eliminar"
 *   confirmType="danger"
 *   (confirmed)="onConfirm()"
 *   (cancelled)="onCancel()">
 * </app-confirm-dialog>
 */
@Component({
  selector: 'app-confirm-dialog',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './confirm-dialog.html',
  styleUrl: './confirm-dialog.scss'
})
export class ConfirmDialogComponent {
  @Input() title: string = '¿Estás seguro?';
  @Input() message: string = 'Esta acción no se puede deshacer.';
  @Input() confirmText: string = 'Confirmar';
  @Input() cancelText: string = 'Cancelar';
  @Input() confirmType: 'primary' | 'danger' = 'primary';
  @Output() confirmed = new EventEmitter<void>();
  @Output() cancelled = new EventEmitter<void>();

  @HostListener('document:keydown.escape')
  onEscapeKey(): void {
    this.onCancel();
  }

  onConfirm(): void {
    this.confirmed.emit();
  }

  onCancel(): void {
    this.cancelled.emit();
  }

  onBackdropClick(event: MouseEvent): void {
    // Solo cerrar si se hace click en el backdrop, no en el modal
    if (event.target === event.currentTarget) {
      this.onCancel();
    }
  }
}

/**
 * EmptyState Styles
 */

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: var(--space-20) var(--space-6);
  gap: var(--space-4);
  min-height: 400px;
}

.empty-state-icon {
  color: var(--gray-300);
  animation: fadeIn var(--transition-slow) var(--ease-out);

  svg {
    display: block;
  }
}

.empty-state-title {
  font-size: var(--text-2xl);
  font-weight: var(--font-bold);
  color: var(--gray-900);
  margin: 0;
  animation: fadeInUp var(--transition-slow) var(--ease-out) 0.1s backwards;
}

.empty-state-message {
  font-size: var(--text-lg);
  color: var(--gray-600);
  max-width: 500px;
  margin: 0;
  line-height: var(--leading-relaxed);
  animation: fadeInUp var(--transition-slow) var(--ease-out) 0.2s backwards;
}

.btn {
  animation: fadeInUp var(--transition-slow) var(--ease-out) 0.3s backwards;
}

/* Mobile responsive */
@media (max-width: 767px) {
  .empty-state {
    padding: var(--space-12) var(--space-4);
    min-height: 300px;
  }

  .empty-state-icon svg {
    width: 48px;
    height: 48px;
  }

  .empty-state-title {
    font-size: var(--text-xl);
  }

  .empty-state-message {
    font-size: var(--text-base);
  }
}

import { Component } from '@angular/core';

@Component({
  selector: 'app-empty-state',
  imports: [],
  templateUrl: './empty-state.html',
  styleUrl: './empty-state.scss',
})
export class EmptyState {

}

import { Component, Input, Output, EventEmitter } from '@angular/core';
import { CommonModule } from '@angular/common';

/**
 * EmptyState Component
 * Muestra un estado vacío con icono, título, mensaje y CTA opcional
 * 
 * @example
 * <app-empty-state
 *   icon="search"
 *   title="No se encontraron espacios"
 *   message="Intenta con otros filtros"
 *   ctaText="Limpiar filtros"
 *   (ctaClick)="clearFilters()">
 * </app-empty-state>
 */
@Component({
  selector: 'app-empty-state',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './empty-state.html',
  styleUrl: './empty-state.scss'
})
export class EmptyStateComponent {
  @Input() icon: 'search' | 'inbox' | 'alert' | 'heart' | 'home' = 'inbox';
  @Input() title: string = 'No hay resultados';
  @Input() message?: string;
  @Input() ctaText?: string;
  @Output() ctaClick = new EventEmitter<void>();

  onCtaClick(): void {
    this.ctaClick.emit();
  }
}

/**
 * RatingStars Styles
 */

.rating-stars {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
}

.stars-container {
  display: flex;
  gap: var(--space-1);

  &.interactive {
    cursor: pointer;

    .star {
      cursor: pointer;
      transition: transform var(--transition-fast);

      &:hover {
        transform: scale(1.1);
      }
    }
  }
}

.star {
  background: none;
  border: none;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color var(--transition-fast);

  &:disabled {
    cursor: default;
  }

  svg {
    display: block;
  }

  &--full {
    color: #FBBF24; /* Yellow-400 */
  }

  &--half {
    color: #FBBF24;
  }

  &--empty {
    color: var(--gray-300);
  }
}

.rating-number {
  font-size: var(--text-sm);
  font-weight: var(--font-semibold);
  color: var(--gray-900);
}

/* Sizes */
.rating-stars--sm {
  .star svg {
    width: 14px;
    height: 14px;
  }

  .rating-number {
    font-size: var(--text-xs);
  }
}

.rating-stars--md {
  .star svg {
    width: 18px;
    height: 18px;
  }

  .rating-number {
    font-size: var(--text-sm);
  }
}

.rating-stars--lg {
  .star svg {
    width: 24px;
    height: 24px;
  }

  .rating-number {
    font-size: var(--text-base);
  }
}

/* Focus states for accessibility */
.star:focus-visible {
  outline: 2px solid var(--primary-600);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

import { Component, Input, Output, EventEmitter } from '@angular/core';
import { CommonModule } from '@angular/common';

/**
 * RatingStars Component
 * Muestra y permite seleccionar rating con estrellas
 * 
 * @example
 * <!-- Read-only -->
 * <app-rating-stars [rating]="4.5" [size]="'md'"></app-rating-stars>
 * 
 * <!-- Interactive -->
 * <app-rating-stars 
 *   [rating]="currentRating" 
 *   [interactive]="true"
 *   (ratingChange)="onRatingChange($event)">
 * </app-rating-stars>
 */
@Component({
  selector: 'app-rating-stars',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './rating-stars.html',
  styleUrl: './rating-stars.scss'
})
export class RatingStarsComponent {
  @Input() rating: number = 0; // 0-5, puede ser decimal (ej: 4.5)
  @Input() size: 'sm' | 'md' | 'lg' = 'md';
  @Input() interactive: boolean = false;
  @Input() showNumber: boolean = true; // Mostrar número al lado
  @Output() ratingChange = new EventEmitter<number>();

  hoveredRating: number = 0;

  /**
   * Array de estrellas (1-5)
   */
  stars = [1, 2, 3, 4, 5];

  /**
   * Determina si una estrella debe estar llena, vacía o media
   */
  getStarType(star: number): 'full' | 'half' | 'empty' {
    const currentRating = this.interactive && this.hoveredRating > 0 
      ? this.hoveredRating 
      : this.rating;

    if (currentRating >= star) {
      return 'full';
    } else if (currentRating >= star - 0.5) {
      return 'half';
    } else {
      return 'empty';
    }
  }

  /**
   * Maneja el hover sobre una estrella
   */
  onStarHover(star: number): void {
    if (this.interactive) {
      this.hoveredRating = star;
    }
  }

  /**
   * Maneja cuando el mouse sale de las estrellas
   */
  onStarsLeave(): void {
    if (this.interactive) {
      this.hoveredRating = 0;
    }
  }

  /**
   * Maneja el click en una estrella
   */
  onStarClick(star: number): void {
    if (this.interactive) {
      this.rating = star;
      this.ratingChange.emit(star);
    }
  }

  /**
   * Formatea el rating para mostrar
   */
  get formattedRating(): string {
    return this.rating.toFixed(1);
  }
}

/**
 * SkeletonList Styles
 */

.skeleton-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-6);

  &--card {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: var(--space-6);
  }
}

.skeleton-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
}

.skeleton-image {
  width: 100%;
  padding-top: 66.67%; /* 3:2 aspect ratio */
}

.skeleton-card-body {
  padding: var(--space-5);
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.skeleton-footer {
  display: flex;
  justify-content: space-between;
  padding-top: var(--space-3);
  border-top: 1px solid var(--gray-200);
}

.skeleton-list-item {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  padding: var(--space-4);
  background: var(--white);
  border-radius: var(--radius-lg);
}

.skeleton-circle {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  flex-shrink: 0;
}

.skeleton-list-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.skeleton-table-row {
  display: flex;
  gap: var(--space-4);
  padding: var(--space-4);
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
}

.skeleton-text {
  height: 16px;
}

/* Mobile responsive */
@media (max-width: 767px) {
  .skeleton-list--card {
    grid-template-columns: 1fr;
  }
}

import { Component, Input } from '@angular/core';
import { CommonModule } from '@angular/common';

/**
 * SkeletonList Component
 * Muestra placeholders animados mientras carga el contenido
 * 
 * @example
 * <app-skeleton-list [count]="6" [type]="'card'"></app-skeleton-list>
 */
@Component({
  selector: 'app-skeleton-list',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './skeleton-list.html',
  styleUrl: './skeleton-list.scss'
})
export class SkeletonListComponent {
  @Input() count: number = 3;
  @Input() type: 'card' | 'list' | 'table' = 'card';

  get items(): number[] {
    return Array.from({ length: this.count }, (_, i) => i);
  }
}

/**
 * SpaceCard Styles
 * Professional card component inspired by Airbnb
 */

.space-card {
  position: relative;
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  cursor: pointer;
  transition: all var(--transition-base);
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  height: 100%;

  &:hover {
    box-shadow: var(--shadow-card-hover);
    transform: translateY(-8px);

    .space-card-image {
      transform: scale(1.1);
    }
  }

  &:focus-visible {
    outline: 2px solid var(--primary-600);
    outline-offset: 2px;
  }
}

.space-card-badge {
  position: absolute;
  top: var(--space-3);
  right: var(--space-3);
  z-index: 10;
  padding: var(--space-1) var(--space-3);
  font-size: var(--text-xs);
  font-weight: var(--font-semibold);
  border-radius: var(--radius-full);
  text-transform: uppercase;
  letter-spacing: var(--tracking-wide);
  background: var(--white);
  box-shadow: var(--shadow-md);
}

.space-card-image-wrapper {
  position: relative;
  width: 100%;
  padding-top: 66.67%; /* 3:2 aspect ratio */
  background: var(--gray-200);
  overflow: hidden;
}

.space-card-image {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.space-card-body {
  padding: var(--space-5);
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.space-card-location {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  font-size: var(--text-sm);
  color: var(--gray-600);

  .icon-location {
    flex-shrink: 0;
    color: var(--primary-600);
  }
}

.space-card-address {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.space-card-distance {
  color: var(--gray-500);
  font-weight: var(--font-medium);
}

.space-card-title {
  font-size: var(--text-lg);
  font-weight: var(--font-semibold);
  color: var(--gray-900);
  margin: 0;
  line-height: var(--leading-tight);
}

.space-card-description {
  font-size: var(--text-sm);
  color: var(--gray-600);
  margin: 0;
  line-height: var(--leading-relaxed);
}

.space-card-amenities {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.amenity-chip {
  display: inline-flex;
  align-items: center;
  padding: var(--space-1) var(--space-2);
  font-size: var(--text-xs);
  color: var(--gray-700);
  background: var(--gray-100);
  border-radius: var(--radius-base);
  font-weight: var(--font-medium);
}

.space-card-capacity {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-sm);
  color: var(--gray-600);

  svg {
    color: var(--gray-500);
  }
}

.space-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding-top: var(--space-3);
  border-top: 1px solid var(--gray-200);
}

.space-card-price {
  display: flex;
  align-items: baseline;
  gap: var(--space-1);
}

.price-amount {
  font-size: var(--text-xl);
  font-weight: var(--font-bold);
  color: var(--gray-900);
}

.price-unit {
  font-size: var(--text-sm);
  color: var(--gray-600);
}

.space-card-rating {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  font-size: var(--text-sm);
}

.rating-count {
  color: var(--gray-600);
}

/* Responsive */
@media (max-width: 767px) {
  .space-card-body {
    padding: var(--space-4);
  }

  .space-card-title {
    font-size: var(--text-base);
  }

  .price-amount {
    font-size: var(--text-lg);
  }
}

import { Component, Input, Output, EventEmitter } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { Space } from '../../../core/models/space.model';
import { PricePipe } from '../../pipes/price.pipe';
import { DistancePipe } from '../../pipes/distance.pipe';

/**
 * SpaceCard Component
 * Card reutilizable para mostrar espacios en listados/grids
 * 
 * Features:
 * - Imagen principal con lazy loading
 * - Precio por hora
 * - Rating y número de reviews
 * - Distancia (opcional)
 * - Capacidad
 * - Amenities principales
 * - Hover effect con elevación
 * - Click para navegar a detalle
 * 
 * @example
 * <app-space-card 
 *   [space]="space" 
 *   [showDistance]="true"
 *   (clicked)="onSpaceClick($event)">
 * </app-space-card>
 */
@Component({
  selector: 'app-space-card',
  standalone: true,
  imports: [CommonModule, RouterModule, PricePipe, DistancePipe],
  templateUrl: './space-card.html',
  styleUrl: './space-card.scss'
})
export class SpaceCardComponent {
  @Input({ required: true }) space!: Space;
  @Input() showDistance: boolean = false;
  @Input() distance?: number; // En metros
  @Output() clicked = new EventEmitter<Space>();

  /**
   * Obtiene la imagen principal del espacio
   */
  get primaryImage(): string {
    const primary = this.space.images?.find(img => img.isPrimary);
    if (primary) {
      return primary.url;
    }

    // Fallback a primera imagen
    if (this.space.images && this.space.images.length > 0) {
      return this.space.images[0].url;
    }

    // Placeholder si no hay imágenes
    return 'assets/images/placeholder-space.jpg';
  }

  /**
   * Obtiene las amenities principales (máximo 3)
   */
  get topAmenities(): string[] {
    if (!this.space.amenities || this.space.amenities.length === 0) {
      return [];
    }
    return this.space.amenities.slice(0, 3);
  }

  /**
   * Maneja el click en la card
   */
  onCardClick(): void {
    this.clicked.emit(this.space);
  }

  /**
   * Obtiene el badge de estado
   */
  get statusBadge(): { label: string; class: string } | null {
    const status = this.space.status?.toUpperCase();

    switch (status) {
      case 'ACTIVE':
        return null; // No mostrar badge para espacios activos
      case 'DRAFT':
        return { label: 'Borrador', class: 'badge-gray' };
      case 'SNOOZED':
        return { label: 'Pausado', class: 'badge-warning' };
      case 'DELETED':
        return { label: 'Eliminado', class: 'badge-error' };
      default:
        return null;
    }
  }
}
